    while((h=bits.readFrame())!=null){if(h.layer()!=3)throw new WavReader.Unsupported();if(Thread.currentThread().isInterrupted())throw new WavReader.Cancelled();SampleBuffer samples=(SampleBuffer)decoder.decodeFrame(h,bits);if(samples.getSampleFrequency()!=rate||samples.getChannelCount()!=channels)throw new WavReader.Unsupported();short[] data=samples.getBuffer();int size=samples.getBufferLength();if(first&&seek)skip+=size;first=false;int start=(int)Math.min(skip,size);skip-=start;int count=0;for(int i=start;i<size;i++){short value=data[i];block[count++]=(byte)value;block[count++]=(byte)(value>>8);}if(bytes+count>0xffffffffL-36)throw new Mp3Decode.NoSpace();if(bytes>=nextCheck){if(directory.getUsableSpace()<36*1024*1024L)throw new Mp3Decode.NoSpace();nextCheck=bytes+4*1024*1024L;}pcm.write(block,0,count);bytes+=count;bits.closeFrame();}
